private class CatalogBuilder {
    val entries = mutableListOf<AdditiveInfo>()
    fun low(code: String, name: String, purpose: String, description: String,
        health: String = LOW_EFFECT, variants: List<String> = emptyList(),
        sources: List<AdditiveSource> = listOf(S.regulation, S.amendment, S.who)) {
        entries += AdditiveInfo(code, name, purpose, description, AdditiveConcern.LOW,
            NORMAL_USE, health, sources, variants)
    }
    fun attention(code: String, name: String, purpose: String, description: String,
        reason: String, health: String, evidence: AdditiveSource,
        variants: List<String> = emptyList(), extra: List<AdditiveSource> = emptyList()) {
        entries += AdditiveInfo(code, name, purpose, description, AdditiveConcern.ATTENTION,
            reason, health, listOf(S.regulation, S.amendment, evidence) + extra, variants)
    }
    fun prohibited(code: String, name: String, purpose: String, description: String,
        health: String = PROHIBITED_EFFECT, evidence: AdditiveSource = S.overview) {
        entries += AdditiveInfo(code, name, purpose, description, AdditiveConcern.HIGH,
            NOT_PERMITTED, health, listOf(S.regulation, S.amendment, evidence))
    }
}

