    low("E261", "Ацетаты калия", "Регулятор кислотности", "Калиевые соли уксусной кислоты. Помогают поддерживать нужную кислотность и свойства рецептуры; наличие соли не сообщает её количество.", variants = subtypes("E261", 2))
    low("E262", "Ацетаты натрия", "Регулятор кислотности и консервант", "Натриевые соли уксусной кислоты, включая диацетат. Поддерживают кислотность и помогают продлевать сохранность хлебобулочных и других продуктов.", variants = subtypes("E262", 2))
    low("E263", "Ацетат кальция", "Регулятор кислотности", "Кальциевая соль уксусной кислоты. Применяется для изменения кислотности и технологических свойств; не означает обогащение продукта значимой дозой кальция.")
    low("E270", "Молочная кислота", "Регулятор кислотности", "Подкисляет пищевые продукты; также естественно образуется при молочнокислом брожении. Название вещества не означает обязательного наличия молочного белка или лактозы.")
    low("E280", "Пропионовая кислота", "Консервант", "Тормозит развитие плесени и отдельных бактерий. В пищевой технологии помогает сохранять, например, хлебобулочные изделия в пределах разрешённых применений.")
    low("E281", "Пропионат натрия", "Консервант", "Натриевая соль пропионовой кислоты. Используется для защиты от плесени; не устраняет последствия неправильного хранения готового продукта.")
    low("E282", "Пропионат кальция", "Консервант", "Кальциевая соль пропионовой кислоты. Часто применяется в хлебопечении для сдерживания плесени и сохранения качества продукта.")
    low("E283", "Пропионат калия", "Консервант", "Калиевая соль пропионовой кислоты. Помогает контролировать развитие плесени в разрешённых категориях пищевой продукции.")
    low("E296", "Яблочная кислота", "Регулятор кислотности", "Придаёт кислый вкус и помогает настроить кислотность напитков и десертов. Встречается в природе в плодах, но технологическая добавка не делает продукт фруктовым.")

    low("E300", "Аскорбиновая кислота", "Антиокислитель", "Известна как витамин C. В пищевой технологии замедляет окисление, помогает сохранять цвет и свойства продукта; по коду нельзя определить витаминную ценность порции.")
    low("E301", "Аскорбат натрия", "Антиокислитель", "Натриевая соль аскорбиновой кислоты. Защищает компоненты продукта от окисления и помогает сохранять окраску, когда требуется менее кислая форма антиокислителя.")
    low("E302", "Аскорбат кальция", "Антиокислитель", "Кальциевая соль аскорбиновой кислоты. Применяется для замедления окисления; технологическое назначение отличается от назначения витаминного препарата.")
    low("E304", "Эфиры аскорбиновой кислоты", "Антиокислитель", "Соединения аскорбиновой и жирных кислот. Удобны для защиты жировых компонентов, где водорастворимая аскорбиновая кислота менее эффективна технологически.", variants = subtypes("E304", 2))
    low("E306", "Концентрат смеси токоферолов", "Антиокислитель", "Смесь веществ группы витамина E. Замедляет прогоркание жиров; присутствие добавки не гарантирует высокую витаминную ценность продукта.")
    low("E307", "Альфа-токоферол", "Антиокислитель", "Одна из форм токоферолов, связанных с витамином E. Защищает жиры от окисления при хранении и переработке.")
    low("E308", "Гамма-токоферол", "Антиокислитель", "Представитель токоферолов. В рецептуре служит для замедления окислительных изменений жиров, а не как самостоятельное средство профилактики заболеваний.")
    low("E309", "Дельта-токоферол", "Антиокислитель", "Форма токоферола с антиокислительными свойствами. Применяется для сохранения качества жировых компонентов пищевой продукции.")
    low("E315", "Изоаскорбиновая кислота", "Антиокислитель", "Также называется эриторбовой кислотой. Помогает сдерживать окисление и изменение окраски; не следует автоматически приравнивать её витаминную активность к витамину C.")
    low("E316", "Изоаскорбат натрия", "Антиокислитель", "Натриевая соль изоаскорбиновой кислоты, или эриторбат натрия. Используется, например, для сохранения окраски мясных изделий и замедления окисления.")
    attention("E322", "Лецитины", "Эмульгатор", "Помогают смешивать жир и воду, используются в шоколаде, выпечке и других продуктах. Сырьём могут быть соя, подсолнечник или другие источники.",
        "Проверьте источник при пищевой аллергии", "E-код сам по себе не определяет наличие аллергенных белков. При аллергии на сою или яйца важно проверить указанное сырьё и аллергенную маркировку конкретного продукта; лецитин не означает аллергию у каждого человека.", S.allergy, subtypes("E322", 2))
    low("E325", "Лактат натрия", "Регулятор кислотности", "Натриевая соль молочной кислоты. Помогает регулировать кислотность и удерживать влагу; слово «лактат» само по себе не означает присутствия лактозы.")
    low("E326", "Лактат калия", "Регулятор кислотности", "Калиевая соль молочной кислоты. Используется для управления кислотностью и сохранения свойств продукта; название не указывает на молочный аллерген.")
    low("E327", "Лактат кальция", "Регулятор кислотности", "Кальциевая соль молочной кислоты. Может помогать поддерживать текстуру и кислотность; количество кальция следует смотреть по отдельным сведениям о пищевой ценности.")
    low("E330", "Лимонная кислота", "Регулятор кислотности", "Придаёт кислый вкус и поддерживает нужный pH в напитках, соусах и консервах. Также связывает ионы металлов, помогая замедлять некоторые изменения продукта.",
        "При нормативном пищевом применении низкая обеспокоенность; лимонная кислота не считается опасной только из-за E-кода. Это не оценка кислотности всего продукта и не разрешение употреблять концентрат кислоты.")
    low("E331", "Цитраты натрия", "Регулятор кислотности", "Натриевые соли лимонной кислоты. Поддерживают кислотность, а в плавленых сырах помогают получить однородную структуру.", variants = subtypes("E331", 3))
    low("E332", "Цитраты калия", "Регулятор кислотности", "Калиевые соли лимонной кислоты. Используются для настройки кислотности и стабильности рецептуры; E-код не показывает содержание калия в порции.", variants = subtypes("E332", 2))
    low("E333", "Цитраты кальция", "Регулятор кислотности", "Кальциевые соли лимонной кислоты. Поддерживают необходимые технологические свойства и кислотность; пищевую ценность продукта оценивают отдельно.", variants = subtypes("E333", 3))
    low("E334", "Винная кислота", "Регулятор кислотности", "Органическая кислота, естественно встречающаяся в винограде. Используется для кислого вкуса и нужной кислотности пищевых продуктов.")
    low("E335", "Тартраты натрия", "Регулятор кислотности", "Натриевые соли винной кислоты. Помогают поддерживать кислотность и технологическую стабильность пищевой смеси.", variants = subtypes("E335", 2))
    low("E336", "Тартраты калия", "Регулятор кислотности", "Калиевые соли винной кислоты; кислая соль известна как винный камень. Используются в том числе для регулирования кислотности и в разрыхляющих смесях.", variants = subtypes("E336", 2))
    attention("E338", "Ортофосфорная кислота", "Регулятор кислотности", "Подкисляет продукты, в том числе некоторые напитки. В отличие от органических кислот служит также источником фосфора.", "Важно при ограничении фосфора в рационе", PHOSPHATE_EFFECT, S.phosphates)
    attention("E339", "Фосфаты натрия", "Регулятор кислотности и стабилизатор", "Натриевые соли фосфорной кислоты. Помогают управлять кислотностью, растворимостью белков и однородностью продукта.", "Важно при ограничении фосфора в рационе", PHOSPHATE_EFFECT, S.phosphates, subtypes("E339", 3))
    attention("E340", "Фосфаты калия", "Регулятор кислотности и стабилизатор", "Калиевые соли фосфорной кислоты. Поддерживают кислотность и технологические свойства, например в молочных продуктах.", "Важно при ограничении фосфора в рационе", PHOSPHATE_EFFECT, S.phosphates, subtypes("E340", 3))
    attention("E341", "Фосфаты кальция", "Регулятор кислотности и разрыхлитель", "Кальциевые соли фосфорной кислоты. В зависимости от формы используются в разрыхляющих смесях и для регулирования свойств продукта.", "Важно при ограничении фосфора в рационе", PHOSPHATE_EFFECT, S.phosphates, subtypes("E341", 3))
    low("E392", "Экстракты розмарина", "Антиокислитель", "Содержат вещества розмарина, замедляющие окисление жиров. Назначение — сохранение качества продукта; это не обязательно ароматизатор со вкусом розмарина.")

    low("E400", "Альгиновая кислота", "Загуститель и стабилизатор", "Полисахарид бурых водорослей. Связывает воду и помогает создавать нужную консистенцию соусов, десертов и других продуктов.")
    low("E401", "Альгинат натрия", "Загуститель и желирующий агент", "Натриевая соль альгиновой кислоты. С ионами кальция может образовывать гель; используется для структуры и удержания воды.")
    low("E402", "Альгинат калия", "Загуститель и стабилизатор", "Калиевая соль альгиновой кислоты. Повышает вязкость и помогает удерживать равномерную структуру водосодержащих продуктов.")
    low("E403", "Альгинат аммония", "Загуститель и стабилизатор", "Соль альгиновой кислоты. Применяется для управления вязкостью и сохранения структуры в предусмотренных регламентом категориях продукции.")
    low("E404", "Альгинат кальция", "Желирующий агент", "Кальциевая соль альгиновой кислоты. Помогает формировать устойчивую гелевую структуру; по наличию кода нельзя оценить содержание пищевых волокон.")
    low("E406", "Агар", "Желирующий агент", "Полисахариды красных водорослей. Образуют гель при охлаждении и помогают придать структуру мармеладу, желе и десертам.")
    attention("E407", "Каррагинан", "Загуститель и стабилизатор", "Полисахарид красных водорослей. Помогает удерживать воду и поддерживать структуру молочных десертов, соусов и мясных изделий.", ALLERGY_REASON,
        "В клинических рекомендациях упоминаются реакции у чувствительных людей. Пищевой каррагинан не следует смешивать с деградированным полигинаном; сообщения о воспалении не доказывают вред обычной порции для всех.", S.allergy, extra = listOf(S.carrageenan))
    attention("E407A", "Обработанные водоросли Eucheuma", "Загуститель и стабилизатор", "Каррагинансодержащий продукт обработки красных водорослей Eucheuma. Отличается от очищенного каррагинана способом получения и составом.", ALLERGY_REASON,
        "Относится к каррагинансодержащим добавкам. Предупреждение касается индивидуальной чувствительности; допустимое пищевое применение само по себе не доказывает воспалительное действие на кишечник.", S.allergy, extra = listOf(S.carrageenan))
    low("E410", "Камедь рожкового дерева", "Загуститель и стабилизатор", "Полисахарид из семян рожкового дерева. Помогает удерживать влагу и стабилизировать структуру, например в мороженом и соусах.")
    attention("E412", "Гуаровая камедь", "Загуститель и стабилизатор", "Полисахарид из семян гуара. Повышает вязкость и снижает расслоение соусов, напитков и десертов.", ALLERGY_REASON, ALLERGY_EFFECT, S.allergy)
    low("E414", "Гуммиарабик", "Стабилизатор и эмульгатор", "Камедь акации, также называемая аравийской. Помогает стабилизировать эмульсии и удерживать ароматические компоненты в равномерном распределении.")
    low("E415", "Ксантановая камедь", "Загуститель и стабилизатор", "Полисахарид, получаемый с помощью ферментации. При небольшом количестве повышает вязкость и помогает сохранять однородность соусов и напитков.")
    low("E417", "Камедь тары", "Загуститель и стабилизатор", "Получается из семян растения тара. Связывает воду и помогает управлять консистенцией, в том числе совместно с другими камедями.")
    low("E418", "Геллановая камедь", "Желирующий агент и стабилизатор", "Полисахарид микробного происхождения. Формирует гели и помогает равномерно распределять взвешенные частицы в напитках.")
    attention("E420", "Сорбит", "Подсластитель и влагоудерживающий агент", "Сахароспирт, выпускаемый также в виде сиропа. Придаёт сладость, удерживает влагу и используется в изделиях без добавленного сахара.", "При избытке возможно слабительное действие", POLYOL_EFFECT, S.polyols, subtypes("E420", 2))
    attention("E421", "Маннит", "Подсластитель", "Сахароспирт, используемый для сладости и технологических свойств. Может присутствовать в жевательной резинке и кондитерских изделиях.", "При избытке возможно слабительное действие", POLYOL_EFFECT, S.polyols)
    low("E422", "Глицерин", "Влагоудерживающий агент", "Помогает сохранять мягкость и влажность пищевого продукта, может служить носителем компонентов. Речь идёт о пищевом глицерине установленной чистоты.")
    attention("E440", "Пектины", "Желирующий агент", "Полисахариды растительного сырья, в том числе яблок и цитрусовых. Образуют гели в джемах и начинках; свойства зависят от формы пектина и рецептуры.", ALLERGY_REASON,
        "Обычно используются как пищевые волокна и желирующие вещества. Клинические рекомендации отмечают возможность аллергических реакций у чувствительных людей; это не означает опасность пектина для всех.", S.allergy, subtypes("E440", 2))
    attention("E450", "Дифосфаты (пирофосфаты)", "Стабилизатор и разрыхлитель", "Соли дифосфорной кислоты. Помогают удерживать влагу, регулировать структуру и работать разрыхляющим смесям; конкретная роль зависит от подтипа.", "Важно при ограничении фосфора в рационе", PHOSPHATE_EFFECT, S.phosphates, subtypes("E450", 7))
    attention("E451", "Трифосфаты", "Стабилизатор", "Соли трифосфорной кислоты. Используются для удержания влаги и управления текстурой, в том числе мясных и рыбных продуктов.", "Важно при ограничении фосфора в рационе", PHOSPHATE_EFFECT, S.phosphates, subtypes("E451", 2))
    attention("E452", "Полифосфаты", "Стабилизатор", "Группа солей полифосфорных кислот. Связывают ионы металлов и помогают сохранять нужную структуру и влагоудерживающие свойства продукта.", "Важно при ограничении фосфора в рационе", PHOSPHATE_EFFECT, S.phosphates, subtypes("E452", 4))
    low("E460", "Целлюлоза", "Наполнитель и стабилизатор", "Растительный полисахарид, используемый в порошковой или микрокристаллической форме. Влияет на текстуру и объём, а не служит усваиваемым сахаром.", variants = subtypes("E460", 2))
    low("E464", "Гидроксипропилметилцеллюлоза", "Загуститель и стабилизатор", "Производное целлюлозы. Связывает воду и помогает формировать структуру, в том числе в безглютеновой выпечке; само название не указывает на наличие глютена.")
    low("E466", "Карбоксиметилцеллюлоза натрия", "Загуститель и стабилизатор", "Также называется целлюлозной камедью. Повышает вязкость и уменьшает расслоение; её технологическая роль отличается от пищевой ценности исходного растительного сырья.")
    low("E471", "Моно- и диглицериды жирных кислот", "Эмульгатор", "Помогают смешивать жир и воду и поддерживать структуру выпечки и десертов. Источник жирных кислот может быть растительным или животным — E-код этого не уточняет.")
    low("E472A", "Эфиры глицерина, уксусной и жирных кислот", "Эмульгатор", "Производные моно- и диглицеридов. Используются для стабильной структуры жировых смесей и пищевых эмульсий.")
